/**
 * events.js - Waseda Calendar イベントデータ管理ファイル
 *
 * 【運営者向け】
 * このファイルにイベント情報を追加・修正・削除することで
 * サイトのイベント情報が更新されます。
 *
 * 一般ユーザーはこのファイルを変更できません。
 * イベント情報の変更は運営者のみが行ってください。
 *
 * 日付形式: YYYY-MM-DD (例: 2025-06-15)
 * 時間形式: HH:MM (例: 14:00)
 *
 * allDay（任意・true）:
 *   開始時刻・終了時刻を持たないイベントのうち、明確に「終日」と確認できる場合だけ true を付ける。
 *   startTime が空でも allDay:true でない通常イベントは、画面上では「時刻未定」と表示する。
 *   学事日程(scope:"schedule")は時刻未指定の場合に終日扱いとするため、個別に付けなくてよい。
 *
 * endDate（任意）:
 *   複数日にわたるイベントの終了日。指定すると、カレンダー上で開始日(date)から
 *   終了日(endDate)まで連続したバーとして表示されます。省略した場合は単日イベントとして扱われます。
 *
 * longRunning（任意・true）:
 *   展示など、14日未満でも月間カレンダーで毎日に繰り返し表示せず「長期開催イベント」欄へ
 *   分離したいものに付ける。14日以上の複数日イベントは従来どおり自動で長期扱いになる。
 *
 * category の選択肢:
 *   "sports" | "culture" | "music" | "theater" | "lecture" | "community" | "other"
 *
 * scope の選択肢:
 *   "schedule" | "circle"
 *   トップページの大枠フィルタ（全部・学事日程・サークルイベント）で使う分類。
 *   "schedule" → 学事日程（授業期間・休業・式典など、大学が主体の日程）
 *   "circle"   → サークル・団体が主催する個別イベント（掲載依頼経由で追加するものは基本これ）
 *   省略した場合は "circle" として扱われる。
 *
 * weeklyClassOnly（任意・true/省略）:
 *   「春学期○週目」「秋学期○週目」「授業予備週/期間」など、授業が行われる期間そのものを表す
 *   学事日程にのみ true を付ける。true が付いたイベントは、日曜日は授業日ではないため
 *   カレンダー上で日曜日には表示されない（script.js の isHiddenOnSunday を参照）。
 *   オープンキャンパス・早稲田祭・卒業式・休業開始/終了・臨時休業など「授業の有無」とは関係ない
 *   学事日程には付けないこと（土日を含む期間全体をそのまま表示したいため）。
 *
 * target の選択肢:
 *   "student" | "obog" | "public" | "applicant"
 *   ※ 複数選択可（配列で指定）
 *
 * campus の選択肢:
 *   "waseda" | "toyama" | "nishiwaseda" | "tokorozawa" | "takadanobaba" | "outside" | "online"
 *
 * feeType の選択肢:
 *   "free" | "paid"
 *
 * isPublished:
 *   true → サイトに表示する
 *   false → 非表示（下書き）
 *
 * imageUrl（任意）:
 *   検索結果の構造化データ（schema.org/Event）に使う画像URL。未指定の場合はサイト共通のOGP画像が使われる。
 *
 * performers（任意・配列）: 同一イベントの出演団体を {name, orgId?} で列挙。
 * mergedInto（任意）: 統合先イベントID。旧レコードは isPublished:false とし、
 *   共有済みURLのリダイレクト用に保持する。
 *
 * orgId（任意）:
 *   organizations.js の団体IDと紐づける場合に指定（例: "org-001"）。
 *   指定すると、終了済み（today > endDate）になった際にその団体のプロフィールページの
 *   「開催実績」一覧に表示されるようになる。既存イベントはorganizerのテキストのままでよく、
 *   orgIdは新規イベントから付与していく運用とする。
 *
 * reactions:
 *   現時点では静的な件数表示のみ。未指定の場合はすべて0件として扱われます。
 *
 * externalUrl（任意）:
 *   イベントの公式サイト・詳細情報ページのURL。カード下部や個別ページ・モーダルの
 *   「公式サイトを見る」「公式・詳細情報を見る」リンクに使われる。
 *
 * registrationUrl（任意）:
 *   参加申込・登録フォームのURL。externalUrl（公式サイト・案内ページ）とは別に、
 *   直接申し込めるフォーム等がある場合に指定する。指定すると個別ページ・モーダルに
 *   externalUrlとは別枠で「参加申し込みはこちら」ボタンが表示される
 *   （externalUrlのみの場合はそちらのボタンのみ表示され、この項目は省略可）。
 *
 * sourceType（任意）:
 *   "submission" → 掲載申請・掲載依頼・情報提供フォーム経由で追加されたイベント。
 *   省略した場合は対象外（運営者が学事日程・情報源監視等から追加したイベントには付けない）。
 *   publishedAtと組み合わせて、同日に複数イベントがある場合の表示順の優先グループ判定に使う
 *   （script.jsのisPriorityToday参照）。過去に遡って既存イベントへ付け直す必要はない。
 *
 * publishedAt（任意・YYYY-MM-DD）:
 *   このイベントを新規にサイト公開した日（JST）。イベント自体の開催日(date)とは別物で、
 *   一度設定したら以後の内容修正でも変更しないこと（lastUpdatedは修正のたびに更新してよいが、
 *   publishedAtは「初回公開日」を固定する値のため混同しないこと）。
 *   sourceType:"submission" と組み合わせた場合のみ意味を持ち、その日(JST)に限り
 *   同日イベントの表示順で優先グループに入る（翌日以降は通常表示に戻る、一時的な効果）。
 *   どちらか一方だけ指定しても優先扱いにはならない（両方が今日の日付と一致して初めて有効）。
 */

